package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
/** Private settings/SQLite and synthetic scores only; no inference/capture, permissions, outputs or services. */
public final class SoundSensitivityStorageTest {
 final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
 interface Task {void run(SharedPreferences prefs,String name)throws Exception;}
 void fixture(Task task)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());String name="sound-sensitivity-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(name,Context.MODE_PRIVATE);try{task.run(prefs,name);}finally{try{assertTrue(prefs.edit().clear().commit());}finally{assertTrue(c.deleteSharedPreferences(name));assertEquals(before,Prefs.of(c).getAll());}}}
 @Test public void absentDefaultsAndSavedPerClassSnapshotRoundTripWithoutConsentChanges()throws Exception{fixture((prefs,name)->{assertEquals(SoundSensitivity.DEFAULT,SoundSensitivitySettings.read(prefs).policy);assertTrue(prefs.getAll().isEmpty());assertTrue(prefs.edit().putString("unrelated","preserved").commit());SoundSensitivity selected=SoundSensitivity.DEFAULT.with("snoring",1).with("speech",3).with("cough",1).with("baby_cry",3);SoundSensitivitySettings.of(prefs).save(selected);SoundSensitivity run=SoundSensitivitySettings.read(c.getSharedPreferences(name,Context.MODE_PRIVATE)).policy;assertEquals(selected,run);SoundSensitivitySettings.of(prefs).save(selected.with("snoring",3));assertEquals(1,run.windows("snoring"));assertEquals(3,SoundSensitivitySettings.read(prefs).policy.windows("snoring"));assertEquals("preserved",prefs.getString("unrelated",""));assertEquals(Set.of("unrelated",SoundSensitivitySettings.KEY),prefs.getAll().keySet());});}
 @Test public void malformedSettingsRejectStrictlyAndSafeReadUsesUnmodifiedDefaults()throws Exception{fixture((prefs,name)->{JSONObject valid=new JSONObject(SoundSensitivityJson.encode(SoundSensitivity.DEFAULT));List<JSONObject> bad=new ArrayList<>();for(Object value:new Object[]{"2",true,JSONObject.NULL,0,4,2.5}){JSONObject row=new JSONObject(valid.toString());row.put("snoring",value);bad.add(row);}JSONObject unknown=new JSONObject(valid.toString());unknown.put("unrelated",1);bad.add(unknown);JSONObject absent=new JSONObject(valid.toString());absent.remove("speech");bad.add(absent);JSONObject version=new JSONObject(valid.toString());version.put("version",2);bad.add(version);for(JSONObject row:bad){assertThrows(IllegalArgumentException.class,()->SoundSensitivityJson.decode(row.toString()));assertTrue(prefs.edit().putString(SoundSensitivitySettings.KEY,row.toString()).commit());Map<String,?> before=new HashMap<>(prefs.getAll());SoundSensitivitySettings.Read read=SoundSensitivitySettings.read(prefs);assertEquals(SoundSensitivity.DEFAULT,read.policy);assertFalse(read.error.isEmpty());assertEquals(before,prefs.getAll());}assertTrue(prefs.edit().putInt(SoundSensitivitySettings.KEY,2).commit());assertFalse(SoundSensitivitySettings.read(prefs).error.isEmpty());assertThrows(IllegalArgumentException.class,()->SoundSensitivityJson.decode("x".repeat(513)));});}
 @Test public void temporalChoicesPersistActualIntervalsWithoutChangingOriginalScoresOrPortableData()throws Exception{fixture((prefs,name)->{String database=name+".db",restored=name+"-restored.db";try(Store store=new Store(c,database)){long id=store.begin(),start=store.rows("SELECT start FROM sessions WHERE id=?",""+id).get(0).getLong("start");SoundSensitivitySettings.of(prefs).save(SoundSensitivity.DEFAULT.with("cough",1));SoundSensitivity snapshot=SoundSensitivitySettings.read(prefs).policy;SoundAnalysis.Group groups=new SoundAnalysis.Group((at,n,category,score)->store.soundEvent(id,at,n*975L,category,score,null),snapshot);groups.add(start,new SoundAnalysis.Result("cough",.91));groups.flush();store.end(id,false,1000,start+1000);JSONObject event=store.rows("SELECT * FROM sound_events").get(0);assertEquals("cough",event.getString("category"));assertEquals(.91,event.getDouble("score"),0);assertEquals(975,event.getLong("duration_ms"));assertTrue(event.isNull("clip"));String evidence=event.toString();JSONObject backup=store.backup();Backup.validate(backup);String portable=backup.toString();SoundSensitivitySettings.of(prefs).save(SoundSensitivity.DEFAULT.with("cough",3));assertEquals(evidence,store.rows("SELECT * FROM sound_events").get(0).toString());assertEquals(portable,store.backup().toString());assertFalse(backup.has("soundSensitivity"));try(Store target=new Store(c,restored)){Backup.restoreData(target,backup);JSONObject loaded=target.rows("SELECT * FROM sound_events").get(0);assertEquals(.91,loaded.getDouble("score"),0);assertEquals(event.getString("model"),loaded.getString("model"));assertEquals(975,loaded.getLong("duration_ms"));assertTrue(loaded.isNull("clip"));}}finally{assertTrue(c.deleteDatabase(database));assertTrue(c.deleteDatabase(restored));}});}
}
